// The daemon's answers. The types come from the Rust source (src/api.rs) through `cargo test`;
// do not edit plugin/ui/src/generated by hand.
import type { DeviceStatus } from "./generated/DeviceStatus";
import type { Kind } from "./generated/Kind";
import type { Latency } from "./generated/Latency";
import type { RelayStatus } from "./generated/RelayStatus";

export type { Discovered } from "./generated/Discovered";
export type { Found } from "./generated/Found";
export type { Kind } from "./generated/Kind";
export type { Latency } from "./generated/Latency";
export type { Missing } from "./generated/Missing";
export type { Status } from "./generated/Status";
export type Device = DeviceStatus;
export type Relay = RelayStatus;

export class ApiError extends Error {
	constructor(
		message: string,
		/** The daemon on this computer is not running. */
		readonly offline: boolean,
	) {
		super(message);
	}
}

/** Relative path: the console serves this page under /plugin-ui/plugover/. */
export async function call<T>(op: string, body?: object): Promise<T> {
	const res = await fetch(`api/${op}`, {
		method: body ? "POST" : "GET",
		headers: body ? { "content-type": "application/json" } : undefined,
		body: body ? JSON.stringify(body) : undefined,
	});
	const data = await res.json().catch(() => ({ ok: false, error: `The page could not reach the plugin (HTTP ${res.status}).` }));
	if (!data.ok) throw new ApiError(data.error ?? "Something went wrong.", Boolean(data.offline));
	return data as T;
}

