/** Same thresholds as `Latency::good` in src/api.rs. */
export function steady(l: Latency) {
	return l.average < 5 && l.jitter < 10;
}

/** Whether version `a` is newer than `b`, both like 0.5.1. */
export function newer(a: string, b: string) {
	const [x, y] = [a, b].map((v) => v.split(".").map(Number));
	for (let i = 0; i < Math.max(x.length, y.length); i++) {
		if ((x[i] ?? 0) !== (y[i] ?? 0)) return (x[i] ?? 0) > (y[i] ?? 0);
	}
	return false;
}
